exercise.solution:
// JavaScript track — same Prisma schema DSL; Zod validates inputs at the JS boundary.
model LabL04Publisher {
  id        Int              @id @default(autoincrement())
  name      String
  magazines LabL04Magazine[]
  @@map("lab_l04_publishers")
}

model LabL04Magazine {
  id          Int             @id @default(autoincrement())
  title       String
  publisherId Int             @map("publisher_id")
  publisher   LabL04Publisher @relation(fields: [publisherId], references: [id])
  @@map("lab_l04_magazines")
}

